<?php
require_once __DIR__.'/includes/auth.php';require_roles(['ADMIN','ORGANIZADOR']);require_once __DIR__.'/includes/helpers.php';$pageTitle='Fixture';
try{$torneos=option_map('torneos');$selected=$_GET['torneo']??($_POST['torneo']??array_key_first($torneos));if($_SERVER['REQUEST_METHOD']==='POST'){$p=['P_ID_TORNEO'=>$_POST['torneo']];oracle_run('BEGIN AV_JP_RM_BE_SP_GENERAR_FIXTURE(:P_ID_TORNEO); END;',$p);flash('success','Fixture generado mediante cursor explícito.');header('Location: gestor_fixture.php?torneo='.urlencode($_POST['torneo']));exit;}$partidas=$selected?oracle_cursor('AV_JP_RM_BE_SP_PARTIDA_LISTAR',['P_ID_TORNEO'=>$selected]):[];}catch(Throwable $e){$error=$e->getMessage();}
include __DIR__.'/includes/header.php';?>
<main class="content"><div class="page-head"><div><h1>🗓 Generación de fixture</h1><p>Gestor 3: Oracle recorre los equipos inscritos con OPEN, FETCH y CLOSE y crea las partidas.</p></div></div><?php if(!empty($error)):?><div class="callout" style="border-color:#ff667d"><?=h($error)?></div><?php endif;?><section class="panel"><form method="post" class="toolbar"><div class="field" style="min-width:320px"><label>Torneo</label><select name="torneo"><?php foreach($torneos??[] as $v=>$l):?><option value="<?=h($v)?>" <?=((string)$v===(string)$selected)?'selected':''?>><?=h($l)?></option><?php endforeach;?></select></div><button class="btn" data-confirm="El fixture solo puede generarse una vez por torneo. ¿Continuar?">Generar fixture</button></form><div class="table-wrap"><table><thead><tr><th>ID</th><th>Ronda</th><th>Local</th><th>Visita</th><th>Fecha</th><th>Marcador</th><th>Estado</th></tr></thead><tbody><?php foreach($partidas??[] as $p):?><tr><td><?=h($p['ID_PARTIDA'])?></td><td><?=h($p['RONDA'])?></td><td><?=h($p['EQUIPO_LOCAL'])?></td><td><?=h($p['EQUIPO_VISITA']?:'BYE')?></td><td><?=h($p['FECHA_HORA'])?></td><td><?=h(($p['PUNTAJE_LOCAL']??'-').' - '.($p['PUNTAJE_VISITA']??'-'))?></td><td><span class="badge <?=h($p['ESTADO'])?>"><?=h($p['ESTADO'])?></span></td></tr><?php endforeach;?></tbody></table></div></section></main><?php include __DIR__.'/includes/footer.php';?>
